import { useMemo } from 'react';
import Cookies from 'js-cookie';
import { useAppSelector } from '@/core/global-store';
import { flattenMePayload, idFromUnknown } from '@/features/selfServices/components/insurances/insurancePage/insuranceHeading';

/** Same resolution as insurance Heading / HR self-service (User id ↔ Employee id). */
export function useResolvedEmployeeId(): number | undefined {
    const authUser = useAppSelector((s) => s.auth.user);
    const me = useAppSelector((s) => s.auth.me);

    return useMemo(() => {
        let cookieId: number | undefined;
        try {
            const u = JSON.parse(Cookies.get('user') || '{}') as { id?: number };
            cookieId = u?.id;
        } catch {
            cookieId = undefined;
        }
        return idFromUnknown(flattenMePayload(me).id) ?? authUser?.id ?? cookieId;
    }, [authUser?.id, me]);
}
