/**
 * Normalize Laravel `check_in` / `check_out`: ISO string, `Y-m-d H:i:s`, or time-only `H:i:s` / `G:i:s`.
 */
export function attendanceFieldToDate(value: unknown, fallbackDayYmd: string): Date | null {
    if (value == null || value === '') return null;

    if (typeof value === 'object' && value !== null && 'date' in (value as Record<string, unknown>)) {
        const dateStr = String((value as { date: string }).date).trim();
        const d = new Date(dateStr.replace(' ', 'T'));
        return Number.isNaN(d.getTime()) ? null : d;
    }

    if (typeof value !== 'string') return null;

    const s = value.trim();
    if (!s) return null;

    if (/^\d{4}-\d{2}-\d{2}/.test(s) || s.includes('T')) {
        const normalized = s.includes('T') || s.includes(' ') ? s.replace(' ', 'T') : `${s}T00:00:00`;
        const d = new Date(normalized);
        return Number.isNaN(d.getTime()) ? null : d;
    }

    const parts = s.split(':').map((p) => Number(String(p).trim()));
    if (parts.some((n) => Number.isNaN(n)) || parts.length < 2) return null;

    const [y, mo, d] = fallbackDayYmd.split('-').map(Number);
    if (!y || !mo || !d) return null;
    return new Date(y, mo - 1, d, parts[0], parts[1] ?? 0, parts[2] ?? 0, 0);
}

/** Laravel `data` is either one model object or a list (Collection). */
export function unwrapAttendanceRow<T extends Record<string, unknown>>(payload: unknown): T | null {
    if (payload == null) return null;
    if (Array.isArray(payload)) {
        const row = payload[0];
        return row && typeof row === 'object' ? (row as T) : null;
    }
    if (typeof payload === 'object') return payload as T;
    return null;
}
